<?php
require_once __DIR__ . '/../includes/config.php';
require_role('admin');db_required();if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$action=$_POST['action'];$s=$pdo->prepare('SELECT * FROM event_requests WHERE id=?');$s->execute([$id]);$r=$s->fetch();if($r){if($action==='approve'){$ins=$pdo->prepare('INSERT INTO events(host_id,title,category,description,event_date,venue,expected_participants,budget,requirements,status) VALUES(?,?,?,?,?,?,?,?,?,\'approved\')');$ins->execute([$r['user_id'],$r['title'],$r['category'],$r['description'],$r['event_date'],$r['venue'],$r['expected_participants'],$r['budget'],$r['requirements']]);$pdo->prepare("UPDATE event_requests SET status='approved',reviewed_at=NOW() WHERE id=?")->execute([$id]);flash('success','Event proposal approved and published.');}else{$pdo->prepare("UPDATE event_requests SET status='rejected',reviewed_at=NOW() WHERE id=?")->execute([$id]);flash('success','Proposal rejected.');}}redirect('/admin/requests.php');}$rows=$pdo->query('SELECT er.*,u.name,u.email FROM event_requests er JOIN users u ON u.id=er.user_id ORDER BY FIELD(er.status,\'pending\',\'approved\',\'rejected\'),er.created_at DESC')->fetchAll();$page_title='Event Requests';require __DIR__.'/../includes/header.php';?><div class="container py-5"><div class="section-kicker">HOD review</div><h2 class="fw-bold mb-4">Event proposals</h2><div class="dash-card overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Proposal</th><th>Host</th><th>Date</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['title'])?></strong><div class="small text-secondary"><?=e($r['category'])?></div></td><td><?=e($r['name'])?></td><td><?=date('d M Y',strtotime($r['event_date']))?></td><td><?=status_badge($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post" class="d-flex gap-2"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="approve" class="btn btn-sm btn-success rounded-pill">Approve</button><button name="action" value="reject" class="btn btn-sm btn-outline-danger rounded-pill">Reject</button></form><?php else:?><span class="small text-secondary">Reviewed</span><?php endif;?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="empty">No event requests.</td></tr><?php endif;?></tbody></table></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
